# Solution Search Script
# This script attempts to find a partition of the given set L into 15 triples (a,b,c) with a+b=c.
# If a solution is found it prints the triples and a positive witness.
# If the search exhausts all possibilities without finding a solution it prints a negative witness.

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

# Pre‑compute all valid triples (a, b, c) with a < b and a+b == c
triples = []
for a in L:
    for b in L:
        if a < b:
            c = a + b
            if c in L and c != a and c != b:
                triples.append((a, b, c))

# Backtracking search for 15 disjoint triples covering L
from collections import defaultdict

# Sort triples to try larger c first (heuristic)
triples.sort(key=lambda t: t[2], reverse=True)

solution = []
used = set()

def backtrack(start):
    if len(solution) == 15:
        if used == L:
            return True
        return False
    if start >= len(triples):
        return False
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        # Choose
        solution.append((a, b, c))
        used.update([a, b, c])
        if backtrack(i + 1):
            return True
        # Unchoose
        solution.pop()
        used.difference_update([a, b, c])
    return False

found = backtrack(0)

if found:
    # Positive witness with concrete result
    result = {"triples": solution}
    print(f"WITNESS: { {\"polarity\": \"positive\", \"evidence\": {\"path\": \"execution://witness\"}, \"data\": result } }")
else:
    # Negative witness – exhaustive search exhausted
    print(f"WITNESS: { {\"polarity\": \"negative\", \"evidence\": {\"path\": \"execution://witness\"}, \"basis\": \"search\", \"search_exhausted\": true, \"nodes_explored\": null, \"method\": \"backtracking\" } }")

import itertools, json, sys
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# generate all valid triples (a,b,c) with a<b and a+b=c
triples = [(a,b,a+b) for a,b in itertools.combinations(L,2) if a+b in L]
# backtracking search for exact cover of 45 elements with 15 triples
used = set()
solution = []

# order triples by frequency heuristic
from collections import defaultdict
freq = defaultdict(int)
for a,b,c in triples:
    freq[a]+=1;freq[b]+=1;freq[c]+=1
triples.sort(key=lambda t: sum(freq[x] for x in t))

sys.setrecursionlimit(10000)

def search(start_idx=0):
    if len(solution)==15:
        if used==L:
            return True
        return False
    # prune if not enough remaining triples
    for i in range(start_idx, len(triples)):
        a,b,c = triples[i]
        if a in used or b in used or c in used:
            continue
        # choose
        used.update([a,b,c])
        solution.append((a,b,c))
        if search(i+1):
            return True
        # backtrack
        used.difference_update([a,b,c])
        solution.pop()
    return False

found = search()
if found:
    witness = {"polarity":"positive","evidence":{"path":"execution://witness"},"data":{"triples":solution}}
    print("WITNESS:", json.dumps(witness))
else:
    witness = {"polarity":"negative","evidence":{"path":"execution://witness"},"basis":"search","search_exhausted":true,"nodes_explored":null,"method":"backtrack"}
    print("WITNESS:", json.dumps(witness))
